from textual.app import ComposeResult
from textual.containers import Horizontal
from textual.widgets import Tree, Static, Header, Footer
from textual.binding import Binding
import os


class DirectoryTree(Tree):
    """A tree widget for exploring directories."""

    def __init__(self, root_path: str = ".", **kwargs):
        super().__init__(root_path, **kwargs)
        self.root_path = root_path

    def on_mount(self) -> None:
        self.root.expand()
        self._populate_node(self.root)

    def _populate_node(self, node) -> None:
        """Recursively populate tree nodes with directory contents."""
        path = node.data
        try:
            entries = sorted(os.listdir(path))
            for entry in entries:
                if entry.startswith('.'):
                    continue
                full_path = os.path.join(path, entry)
                if os.path.isdir(full_path):
                    node.add(f"📁 {entry}", full_path)
                else:
                    node.add(f"📄 {entry}", full_path)
        except (PermissionError, FileNotFoundError):
            pass

    def on_tree_node_expanded(self, event: Tree.NodeExpanded) -> None:
        """Handle node expansion to lazy-load children."""
        if not event.node.children:
            self._populate_node(event.node)

    def on_tree_node_selected(self, event: Tree.NodeSelected) -> None:
        """Handle node selection to display file contents."""
        path = event.node.data
        text_display = self.app.query_one("#text-panel", Static)

        if os.path.isfile(path):
            try:
                with open(path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
                text_display.update(content)
            except Exception as e:
                text_display.update(f"Error reading file: {e}")
        else:
            text_display.update(f"Directory: {path}")


class FileExplorerApp(ComposeResult):
    """A two-panel file explorer app."""

    BINDINGS = [
        Binding("q", "quit", "Quit", show=True),
    ]

    CSS = """
    Screen {
        layout: vertical;
    }

    Horizontal {
        height: 1fr;
    }

    #tree-panel {
        width: 30%;
        border: solid $primary;
        background: $surface;
    }

    #text-panel {
        width: 70%;
        border: solid $primary;
        background: $panel;
        overflow: auto;
    }
    """

    def compose(self) -> ComposeResult:
        yield Header()
        with Horizontal():
            yield DirectoryTree(id="tree-panel")
            yield Static(id="text-panel")
        yield Footer()


if __name__ == "__main__":
    app = FileExplorerApp()
    app.run()

